from lib import *
S = SS('f91')
R = J('f91'); ex = R['exhaust']; cc = R['conn_cost']; w1, w3 = R['workers']['1'], R['workers']['3']; of = R['overflow_closed']
steps = [
    step("默认配置的连接池:QueuePool,pool_size=5、max_overflow=10、timeout=30 秒、recycle=-1(不回收)、pre_ping=False。刚创建时 PostgreSQL 上 0 个连接(惰性创建);借出 2 个并执行 SQL 后连接数 2,池状态 Checked out 2;归还 1 个后,这个连接留在池里(Connections in pool: 1),PG 连接数仍是 2;engine.dispose() 之后连接数回到 0。", t=tl(S(1)), done=lidx(S(1), '类型', '借出 2 个', '归还 1 个', 'dispose'), kv=KV([['默认', 'size 5 + overflow 10,timeout 30 s'], ['连接', '惰性创建,归还后留在池里']], ['默认'])),
    step(f"连接池耗尽:pool_size=2、max_overflow=1、pool_timeout=1 秒,同时借 3 个都成功(2 + 1 个溢出,PG 上 3 个连接);借第 4 个等了 {ex[0]:.0f} ms 后抛 {ex[1]}「QueuePool limit of size 2 overflow 1 reached, connection timed out, timeout 1.00」。归还连接时:池里还有空位就留在池里(归还 1 个、2 个后 PG 连接数仍是 {of[0]}、{of[1]}),三个都归还后池里只保留 pool_size=2 个,多出的那个溢出连接被关闭(PG 连接数 {of[2]})。", t=tl(S(2)), mark=lidx(S(2), 'TimeoutError'), done=lidx(S(2), '借 3 个', '三个都归还'), kv=KV([['超过 size + overflow', f'等 timeout 后 TimeoutError'], ['溢出连接', '归还时池已满才关闭']], ['超过 size + overflow'])),
    step(f"服务端把空闲连接杀掉(pg_terminate_backend)之后的下一次查询:默认的池抛 OperationalError「terminating connection due to administrator command」,之后坏连接被丢弃,再查一次成功;pool_pre_ping=True 时池在借出连接前先探测,发现连接已坏就换一个新的,这次查询直接成功。", t=tl(S(3)), mark=lidx(S(3), '默认(无 pre_ping)'), done=lidx(S(3), 'pool_pre_ping=True'), kv=KV([['无 pre_ping', '第一次查询失败'], ['pre_ping=True', '先探测,坏了就换']], ['pre_ping=True'])),
    step(f"每次新建连接与从池里取:借连接加 select 1 的耗时(200 次中位数),QueuePool {cc['QueuePool']:.2f} ms,NullPool(不池化,每次新建并关闭){cc['NullPool']:.2f} ms,约 {cc['NullPool'] / cc['QueuePool']:.0f} 倍(本机回环、无 TLS,真实网络与 TLS 下新建连接贵得多)。", b=bars([['QueuePool', cc['QueuePool'], f"{cc['QueuePool']:.2f} ms"], ['NullPool', cc['NullPool'], f"{cc['NullPool']:.2f} ms"]], cc['NullPool'], mark=[1], done=[0]), t=tl(S(4)), done=lidx(S(4), 'QueuePool'), mark=lidx(S(4), 'NullPool'), kv=KV([['QueuePool', f"{cc['QueuePool']:.2f} ms"], ['NullPool', f"{cc['NullPool']:.2f} ms"]], ['QueuePool'])),
    step(f"gunicorn 多个 worker:每个 worker 进程有自己的连接池(这里每池 3 + 2 = 5)。40 个并发请求(每个查询 0.5 秒):1 个 worker 时 PG 上最多同时 {w1[0]} 个连接、总耗时 {w1[1]:.1f} 秒(请求排队等池里的连接);3 个 worker 时最多 {w3[0]} 个连接(3 × 5)、总耗时 {w3[1]:.1f} 秒。数据库的 max_connections 要按 worker 数 × (pool_size + max_overflow) 来估算。", b=bars([['1 个 worker', w1[1], f'{w1[1]:.1f} s / {w1[0]} 连接'], ['3 个 worker', w3[1], f'{w3[1]:.1f} s / {w3[0]} 连接']], w1[1], mark=[0], done=[1]), t=tl(S(5)), done=lidx(S(5), '3 个 worker'), mark=lidx(S(5), '1 个 worker'), kv=KV([['PG 连接数上限', 'worker 数 × (size + overflow)'], ['池太小', '请求排队']], ['PG 连接数上限'])),
]
A = mkartf('f91', 91, 'Flask,SQLAlchemy,连接池,QueuePool,pre_ping,真实验证,动画演示',
    f'在真实的 PostgreSQL 上实测 SQLAlchemy 连接池:默认 QueuePool 5 + 10、惰性创建、耗尽时 {ex[0]:.0f} ms 后 TimeoutError、溢出连接的关闭时机、服务端杀掉连接后 pre_ping 的作用、池化 {cc["QueuePool"]:.2f} ms 对不池化 {cc["NullPool"]:.2f} ms、多 worker 下 PG 连接数是各池之和({w3[0]} 个)。',
    '连接池默认是多大?耗尽时会怎样?连接被服务端断掉之后会不会出错?多个 gunicorn worker 会把数据库连接数撑到多少?这篇用真实的 PostgreSQL 逐项验证。',
    [('5 + 10', 'QueuePool 默认的 pool_size 与 max_overflow'), (f'{w3[0]} 个', '3 个 gunicorn worker、每池 3 + 2 时 PG 上同时出现的最大连接数'), (f'{cc["NullPool"] / cc["QueuePool"]:.0f} 倍', 'NullPool 相对 QueuePool 的单次借连接耗时(本机回环)')],
    [('默认配置', '<p>上一篇:<a href="flask-rollback-behavior.html">Rollback 的实际行为</a>;下一篇:<a href="flask-pool-checkout-release.html">Pool Checkout 与连接释放</a>。</p>'), ('连接池耗尽', None), ('连接被断开与 pre_ping', '<p>第 100 篇会专门讲断线后的恢复。</p>'), ('池化的收益', None), ('多个 worker', '<p>这一节用 gunicorn 的 gthread worker,每个 worker 进程里一个独立的 Engine。</p>')],
    steps, [ENV_F + '。Flask-SQLAlchemy 3.1.1、psycopg 3.3.6、自己起的 PostgreSQL(非默认端口)', '没有验证:pool_recycle 在 MySQL 的 wait_timeout 下的作用、真实网络与 TLS 下新建连接的耗时、PgBouncer 等外部连接池、预加载应用(--preload)后在 fork 里共享 Engine 的问题、pool_use_lifo 与 pool_reset_on_return 的取值'], '数据库连接池', panels=[('t', 'term', '实验输出'), ('b', 'bars', '耗时'), ('kv', 'kv', '要点')])
